  ('class', 'barbaro', 'Bárbaro', 'published', $class${"description":"O Bárbaro domina a linha de frente por meio de força, resistência e pressão constante. Quanto mais perigosa a batalha se torna, mais Fúria ele acumula para ampliar dano e sobrevivência. É excelente em quebrar formações e permanecer lutando sob pressão, mas sofre contra controle à distância e inimigos que negam aproximação.","imageUrl":"","difficulty":3,"complexity":"Médio","specialization":"Híbrido (DPS Físico / Tanque)","primaryAttributes":["FOR","RES"],"affinities":{"FOR":5,"DEF":3,"RES":4,"INI":3,"INT":1,"ARC":1},"mechanic":{"name":"Fúria","description":"Recurso exclusivo da classe, desenvolvido pela passiva Coração Indomável e por suas habilidades."},"passive":{"name":"Coração Indomável","description":"Recebe 1 ponto de Fúria ao causar ou sofrer dano, até 10. Cada ponto concede 1% de dano físico. Ao alcançar 10, consome toda a Fúria no fim do turno para recuperar 8% do HP máximo e ficar Implacável até o próximo turno, reduzindo efeitos de controle em 1 turno."},"progression":[{"key":"golpe-selvagem","name":"Golpe Selvagem","level":1,"category":"Ataque","type":"Ativa","effect":"Causa 1x FOR como dano físico em um alvo. Se cumprir a condição central de Fúria, causa 0,2x FOR adicional.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1},{"attribute":"FOR","multiplier":0.2}]},{"key":"rugido-intimidador","name":"Rugido Intimidador","level":1,"category":"Controle","type":"Ativa","effect":"Aplica Lentidão de 20% e impede reações comuns por 1 turno. Resistência reduz a duração, mas não remove a penalidade de INI.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":1,"scaling":[]},{"key":"investida-do-touro","name":"Investida do Touro","level":10,"category":"Mobilidade","type":"Ativa","effect":"Desloca até 3 casas sem provocar a primeira reação comum. Se terminar em posição favorável, gera 1 Fúria.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":3,"area":0,"duration":0,"scaling":[]},{"key":"pele-de-ferro","name":"Pele de Ferro","level":10,"category":"Defesa","type":"Ativa","effect":"Reduz o dano recebido em 26% por 1 turno e concede um escudo de 0,84x RES. Recarga de 4 turnos.","kind":"shield","damageType":"none","target":"self","resource":"none","cost":0,"cooldown":4,"range":1,"area":0,"duration":1,"scaling":[{"attribute":"RES","multiplier":0.84}]},{"key":"machado-giratorio","name":"Machado Giratório","level":20,"category":"Área","type":"Ativa","effect":"Atinge uma área de 2 casas, causando 1,01x FOR como dano físico. O alvo central recebe 25% a mais. Recarga de 4 turnos.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":4,"range":1,"area":2,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1.01}]},{"key":"sangue-fervente","name":"Sangue Fervente","level":20,"category":"Sustentação","type":"Ativa","effect":"Recupera 8% do HP máximo e recebe 16% de RES por 2 turnos. Só pode ser usada abaixo de 60% do HP.","kind":"heal","damageType":"none","target":"self","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":2,"scaling":[]},{"key":"quebra-fileiras","name":"Quebra-Fileiras","level":30,"category":"Ataque","type":"Ativa","effect":"Causa 1,45x FOR como dano físico em um alvo. Se cumprir a condição central de Fúria, causa 0,2x FOR adicional.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1.45},{"attribute":"FOR","multiplier":0.2}]},{"key":"desafio-ancestral","name":"Desafio Ancestral","level":30,"category":"Provocação","type":"Ativa","effect":"Provoca inimigos em até 2 casas por 1 turno e reduz em 23% o dano que causam a outros alv