cumulando até 4 vezes. Trocar de alvo remove metade dos acúmulos."},"skills":[{"key":"corte-devastador","name":"Corte Devastador","level":50,"category":"Ativa","type":"Ativa","effect":"Causa 1,7x FOR e concede uma ação de ataque básico com 60% da potência se o alvo estiver marcado.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1.7}]},{"key":"passos-sobre-corpos","name":"Passos sobre Corpos","level":50,"category":"Ativa","type":"Ativa","effect":"Avança 4 casas; cada inimigo atravessado recebe 0,7x FOR e não pode realizar reação contra o usuário.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":0.7}]},{"key":"fome-de-batalha","name":"Fome de Batalha","level":50,"category":"Ativa","type":"Ativa","effect":"Por 3 turnos, eliminações concedem 12% de FOR e reduzem uma recarga em 1 turno.","kind":"utility","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":3,"scaling":[]},{"key":"ruptura-do-colosso","name":"Ruptura do Colosso","level":50,"category":"Ativa","type":"Ativa","effect":"Golpeia uma área curta por 1,4x FOR, quebrando 25% da DEF por 2 turnos.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":2,"scaling":[{"attribute":"FOR","multiplier":1.4}]},{"key":"fim-da-linha","name":"Fim da Linha","level":50,"category":"Ultimate","type":"Ultimate","effect":"Por 3 turnos, recebe 25% de FOR, uma ação de ataque adicional por turno com 60% da potência e não perde bônus ao trocar de alvo. Uma vez por combate.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":3,"scaling":[]}]},{"key":"guardiao-das-tribos","name":"Guardião das T