  ('class', 'alquimista', 'Alquimista', 'published', $class${"description":"O Alquimista prepara fórmulas que curam, fortalecem, explodem ou alteram áreas do campo. Sua força está na adaptação: a mesma rodada pode ser dedicada a salvar um aliado ou impedir o avanço inimigo. Exige planejamento de Reagentes e leitura do combate; se for surpreendido sem preparações, perde grande parte do impacto.","imageUrl":"","difficulty":4,"complexity":"Difícil","specialization":"Híbrido (Suporte / Controle de Grupo)","primaryAttributes":["INT","ARC"],"affinities":{"FOR":1,"DEF":2,"RES":3,"INI":3,"INT":4,"ARC":5},"mechanic":{"name":"Reagentes","description":"Recurso exclusivo da classe, desenvolvido pela passiva Laboratório Portátil e por suas habilidades."},"passive":{"name":"Laboratório Portátil","description":"Começa o combate com 3 Reagentes e prepara 1 no início de cada turno, até 5. Habilidades alquímicas podem gastar 1 Reagente para escolher uma Melhoria: +20% de potência, +1 turno de duração ou ampliar a área em 1 casa. A mesma Melhoria não pode ser repetida na mesma habilidade."},"progression":[{"key":"frasco-incendiario","name":"Frasco Incendiário","level":1,"category":"Área","type":"Ativa","effect":"Atinge uma área de 2 casas, causando 0,77x INT como dano mágico. O alvo central recebe 25% a mais. Recarga de 5 turnos.","kind":"damage","damageType":"magic","target":"enemy","resource":"none","cost":0,"cooldown":5,"range":1,"area":2,"duration":0,"scaling":[{"attribute":"INT","multiplier":0.77}]},{"key":"tonico-restaurador","name":"Tônico Restaurador","level":1,"category":"Cura","type":"Ativa","effect":"Restaura 0,82x ARC + 0,25x INT do HP de um aliado. Custa 30 Mana; recarga de 4 turnos.","kind":"heal","damageType":"magic","target":"ally","resource":"mana","cost":30,"cooldown":4,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"ARC","multiplier":0.82},{"attribute":"INT","multiplier":0.25}]},{"key":"bomba-de-fumaca","name":"Bomba de Fumaça","level":10,"category":"Controle","type":"Ativa","effect":"Aplica Lentidão de 20% e impede reações comuns por 1 turno. Resistência reduz a duração, mas não remove a penalidade de INI.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":1,"scaling":[]},{"key":"elixir-de-pedra","name":"Elixir de Pedra","level":10,"category":"Proteção","type":"Ativa","effect":"Concede a um aliado escudo igual a 0,84x ARC por 2 turnos. Recarga de 4 turnos.","kind":"shield","damageType":"none","target":"ally","resource":"none","cost":0,"cooldown":4,"range":1,"area":0,"duration":2,"scaling":[{"attribute":"ARC","multiplier":0.84}]},{"key":"acido-corrosivo","name":"Ácido Corrosivo","level":20,"category":"Dano contínuo","type":"Ativa","effect":"Aplica dano contínuo de 0,53x INT no início do turno do alvo por 3 turnos. Reaplicar renova, mas não acumula.","kind":"damage","damageType":"magic","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":3,"scaling":[{"attribute":"INT","multiplier":0.53}]},{"key":"catalisador-veloz","name":"Catalisador Veloz","level":20,"category":"Suporte","type":"Ativa","effect":"Um aliado recebe 18% de seu atributo principal e 10% de INI por 2 turnos. Custa 50 Mana.","kind":"utility","damageType":"none","target":"ally","resource":"mana","cost":50,"cooldown":0,"range":1,"area":0,"duration":2,"scaling":[]},{"key":"gel-criogenico","name":"Gel Criogênico","level":30,"category":"Controle de área","type":"Ativa","effect":"Cria uma área de 2 casas por 2 turnos. Inimigos nela perdem 27% de INI e sofrem 1,13x INT ao entrar pela primeira vez.","kind":"damage","damageType":"magic","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":2,"duration":2,"scaling":[{"attribute":"INT","multiplier":1.13}]},{"key":"antidoto-universal","name":"Antídoto Universal","level":30,"category":"Purificação","type":"Ativa","effect":"Remove até dois efeitos negativos de um aliado e concede 20% de RES con