  ('class', 'bardo', 'Bardo', 'published', $class${"description":"O Bardo conduz o combate como uma apresentação, alternando melodias de fortalecimento, cura e perturbação. Ao combinar Notas na ordem correta, cria Refrões que alteram o ritmo de toda a equipe. Seu potencial coletivo é enorme, mas exige sequência, posicionamento e proteção para que a composição não seja interrompida.","imageUrl":"","difficulty":4,"complexity":"Difícil","specialization":"Híbrido (Suporte / Controle de Grupo)","primaryAttributes":["INI","ARC"],"affinities":{"FOR":1,"DEF":2,"RES":3,"INI":4,"INT":3,"ARC":5},"mechanic":{"name":"Notas","description":"Recurso exclusivo da classe, desenvolvido pela passiva Composição de Batalha e por suas habilidades."},"passive":{"name":"Composição de Batalha","description":"Cada habilidade gera uma Nota de Coragem, Harmonia ou Discórdia, até 3. Ao formar três Notas, elas são consumidas e ativam um Refrão: três iguais ampliam o efeito em 30%; três diferentes concedem 10% de INI e 10% de potência de suporte aos aliados por 1 turno."},"progression":[{"key":"acorde-inspirador","name":"Acorde Inspirador","level":1,"category":"Suporte","type":"Ativa","effect":"Um aliado recebe 14% de seu atributo principal e 10% de INI por 2 turnos. Custa 30 Mana.","kind":"utility","damageType":"none","target":"ally","resource":"mana","cost":30,"cooldown":0,"range":1,"area":0,"duration":2,"scaling":[]},{"key":"nota-dissonante","name":"Nota Dissonante","level":1,"category":"Enfraquecimento","type":"Ativa","effect":"Reduz o atributo ofensivo principal do alvo em 14% e sua RES em 10% por 2 turnos. Recarga de 5 turnos.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":5,"range":1,"area":0,"duration":2,"scaling":[]},{"key":"balada-restauradora","name":"Balada Restauradora","level":10,"category":"Cura","type":"Ativa","effect":"Restaura 0,94x ARC + 0,25x INT do HP de um aliado. Custa 40 Mana; recarga de 3 turnos.","kind":"heal","damageType":"ma