  ('class', 'druida', 'Druida', 'published', $class${"description":"O Druida canaliza os ciclos da natureza para curar, controlar terreno, invocar criaturas e assumir formas animais. Alterna entre Crescimento e Declínio, modificando o efeito das próprias habilidades. É versátil e resistente, mas exige antecipação: escolher o ciclo errado reduz o impacto justamente quando a equipe mais precisa.","imageUrl":"","difficulty":4,"complexity":"Difícil","specialization":"Híbrido (Invocador / Suporte)","primaryAttributes":["RES","ARC"],"affinities":{"FOR":2,"DEF":3,"RES":4,"INI":2,"INT":3,"ARC":5},"mechanic":{"name":"Ciclos","description":"Recurso exclusivo da classe, desenvolvido pela passiva Roda das Estações e por suas habilidades."},"passive":{"name":"Roda das Estações","description":"Começa em Crescimento. Após usar duas habilidades, alterna para Declínio. Crescimento aumenta curas e escudos em 15%; Declínio aumenta dano e controle em 15%. Ao alternar, o Druida recupera 3% do HP máximo e 10 de Mana."},"progression":[{"key":"espinhos-despertos","name":"Espinhos Despertos","level":1,"category":"Controle de área","type":"Ativa","effect":"Cria uma área de 2 casas por 2 turnos. Inimigos nela perdem 18% de INI e sofrem 0,77x INT ao entrar pela primeira vez.","kind":"damage","damageType":"magic","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":2,"duration":2,"scaling":[{"attribute":"INT","multiplier":0.77}]},{"key":"seiva-restauradora","name":"Seiva Restauradora","level":1,"category":"Cura","type":"Ativa","effect":"Restaura 0,82x ARC + 0,25x INT do HP de um aliado. Custa 30 Mana; recarga de 4 turnos.","kind":"heal","damageType":"magic","target":"ally","resource":"mana","cost":30,"cooldown":4,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"ARC","multiplier":0.82},{"attribute":"INT","multiplier":0.25}]},{"key":"forma-do-lobo","name":"Forma do Lobo","level":10,"category":"Transformação","type":"Ativa","effect":"Assume forma ofensiva por 3 turnos: