  ('class', 'espadachim', 'Espadachim', 'published', $class${"description":"O Espadachim é um duelista técnico que alterna Posturas para responder ao adversário. Encadeia cortes, aparos e passos curtos, premiando leitura de turno e execução precisa. Brilha contra um único oponente e pode neutralizar ataques previsíveis, mas tem alcance limitado e menor impacto quando cercado por muitos inimigos.","imageUrl":"","difficulty":4,"complexity":"Difícil","specialization":"DPS Físico","primaryAttributes":["FOR","INI"],"affinities":{"FOR":5,"DEF":2,"RES":2,"INI":4,"INT":1,"ARC":1},"mechanic":{"name":"Posturas","description":"Recurso exclusivo da classe, desenvolvido pela passiva Três Posturas e por suas habilidades."},"passive":{"name":"Três Posturas","description":"No início do turno, escolha Guarda, Corte ou Passo. Guarda concede 10% de DEF; Corte concede 10% de dano físico; Passo concede 10% de INI e +1 casa no primeiro deslocamento. Repetir a mesma Postura reduz o bônus pela metade, incentivando alternância."},"progression":[{"key":"corte-ascendente","name":"Corte Ascendente","level":1,"category":"Ataque","type":"Ativa","effect":"Causa 1x FOR como dano físico em um alvo. Se cumprir a condição central de Posturas, causa 0,2x FOR adicional.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1},{"attribute":"FOR","multiplier":0.2}]},{"key":"aparo-rapido","name":"Aparo Rápido","level":1,"category":"Reação","type":"Ativa","effect":"Assume reação até o próximo turno: reduz o primeiro dano recebido em 23% e responde com 0,85x FOR.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":0.85}]},{"key":"estocada-longa","name":"Estocada Longa","level":10,"category":"Linha","type":"Ativa","effect":"Ataca em linha de até 6 casas, causando 1,15x FOR e ignorando 15% da DEF. Cada alvo após o primeiro recebe 15% menos dano.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":6,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1.15}]},{"key":"passo-lateral","name":"Passo Lateral","level":10,"category":"Mobilidade","type":"Ativa","effect":"Desloca até 3 casas sem provocar a primeira reação comum. Se terminar em posição favorável, gera 1 Posturas.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":3,"area":0,"duration":0,"scaling":[]},{"key":"circulo-de-aco","name":"Círculo de Aço","level":20,"category":"Área","type":"Ativa","effect":"Atinge uma área de 2 casas, causando 1,01x FOR como dano físico. O alvo central recebe 25% a mais. Recarga de 4 turnos.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":4,"range":1,"area":2,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1.01}]},{"key":"leitura-da-lamina","name":"Leitura da Lâmina","level":20,"category":"Fortalecimento","type":"Ativa","effect":"Por 2 turnos, recebe 18% de FOR e 10% de INI. A primeira habilidade usada durante o efeito tem recarga reduzida em 1 turno.","kind":"utility","damageType":"physical","target":"self","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":2,"scaling":[]},{"key":"quebra-guarda","name":"Quebra-Guarda","level":30,"category":"Ataque / Debuff","type":"Ativa","effect":"Causa 1,35x FOR e reduz DEF e RES do alvo em 18% por 2 turnos.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":2,"scaling":[{"attribute":"FOR","multiplier":1.35}]},{"key":"resposta-perfeita","name":"Resposta Perfeita","level":30,"category":"Reação","type":"Ativa","effect":"Assume reação até o próximo turno: reduz o primeiro dano recebido em 32% e responde com 1,15x FOR.","kind":"damage","damageType":"physi