."},"skills":[{"key":"primeira-forma","name":"Primeira Forma","level":50,"category":"Ativa","type":"Ativa","effect":"Causa 1,7x FOR e concede uma ação de ataque básico com 60% da potência se o alvo estiver marcado.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1.7}]},{"key":"segunda-forma","name":"Segunda Forma","level":50,"category":"Ativa","type":"Ativa","effect":"Avança 4 casas; cada inimigo atravessado recebe 0,7x FOR e não pode realizar reação contra o usuário.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":0.7}]},{"key":"terceira-forma","name":"Terceira Forma","level":50,"category":"Ativa","type":"Ativa","effect":"Por 3 turnos, eliminações concedem 12% de FOR e reduzem uma recarga em 1 turno.","kind":"utility","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":3,"scaling":[]},{"key":"forma-vazia","name":"Forma Vazia","level":50,"category":"Ativa","type":"Ativa","effect":"Golpeia uma área curta por 1,4x FOR, quebrando 25% da DEF por 2 turnos.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":2,"scaling":[{"attribute":"FOR","multiplier":1.4}]},{"key":"mil-cortes-em-um","name":"Mil Cortes em Um","level":50,"category":"Ultimate","type":"Ultimate","effect":"Por 3 turnos, recebe 25% de FOR, uma ação de ataque adicional por turno com 60% da potência e não perde bônus ao trocar de alvo. Uma vez por combate.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":3,"scaling":[]}]},{"key":"duelista-da-rosa","name":"Duelista da Rosa","description":"Especializa desafios individuais, aparos e punições elegantes.","passive":{"name":"Duelista da Rosa","description":"Aparar ou evitar completamente um ataque concede 0,15x FOR ao próximo contra-ataque e +1 casa de alcance."},"skills":[{"key":"convite-ao-duelo","name":"Convite ao Duelo","level":50,"category":"Ativa","type":"Ativa","effect":"Prepara um contra-ataque de 1,5x FOR contra o primeiro inimigo que o atingir.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1.5}]},{"key":"petala-cortante","name":"Pétala Cortante","level":50,"category":"Ativa","type":"Ativa","effect":"Anula o primeiro empurrão, puxão ou derrubada sofrido e reposiciona 2 casas.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[]},{"key":"passo-carmesim","name":"Passo Carmesim","level":50,"category":"Ativa","type":"Ativa","effect":"Desafia um alvo; sempre que ele errar, sofre 0,9x FOR.","kind":"utility","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":0.9}]},{"key":"reverencia-final","name":"Reverência Final","level":50,"category":"Ativa","type":"Ativa","effect":"Durante 2 turnos, aparos bem-sucedidos reduzem todas as recargas em 1 turno, uma vez por rodada.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[]},{"key":"a-ultima-danca","name":"A Última Dança","level":50,"category":"Ultimate","type":"Ultimate","effect":"Por 2 turnos, reduz em 50% todo dano frontal e responde a cada ataque recebido com 1x FOR, limitado a três respostas por rodada. Uma vez por combate.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":2,"scaling":[{"attribute":"FOR","multiplier":1}]}]}]}$class$::jsonb, now()),
  ('class', 'feiticeiro', 'Feiticeiro', 'published', $class${"description":"O Feiticeiro manifesta magia de forma instintiva, explosiva e imprevisível. Acumula Sobrecarga ao lançar feitiços e pode liberá-la para alterar alcance, dano ou velocidade de conjuração. Oferece grande poder imediato e mobilidade mágica, mas correr riscos demais pode causar instabilidade e deixá-lo exposto.","imageUrl":"","difficulty":3,"complexity":"Médio","specialization":"DPS Mágico","primaryAttributes":["INI","INT"],"affinities":{"FOR":1,"DEF":1,"RES":2,"INI":4,"INT":5,"ARC":3},"mechanic":{"name":"Sobrecarga","description":"Recurso exclusivo da classe, desenvolvido pela passiva Magia no Sangue e por suas habilidades."},"passive":{"name":"Magia no Sangue","description":"Cada habilidade mágica gera 1 Sobrecarga, até 5. Antes de conjurar, pode consumir 3 para aplicar uma Metamagia: +20% de dano, +2 casas de alcance ou conjuração sem provocar reações. Ao terminar o turno com 5, sofre 5% do HP máximo e perde 2 Sobrecargas."},"progression":[{"key":"dardo-elemental","name":"Dardo Elemental","level":1,"category":"Magia","type":"Ativa","effect":"Causa 1x INT como dano mágico a até 6 casas. Custa 30 Mana; recarga de 4 turnos.","kind":"damage","damageType":"magic","target":"enemy","resource":"mana","cost":30,"cooldown":4,"range":6,"area":0,"duration":0,"scaling":[{"attribute":"INT","multiplier":1}]},{"key":"salto-arcano","name":"Salto Arcano","level":1,"category":"Mobilidade","type":"Ativa","effect":"Desloca até 2 casas sem provocar a primeira reação comum. Se terminar em posição favorável, gera 1 Sobrecarga.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":2,"area":0,"duration":0,"scaling":[]},{"key":"explosao-repentina","name":"Explosão Repentina","level":10,"category":"Área","type":"Ativa","effect":"Atinge uma área de 2 casas, causando 0,89x INT como dano mágico. O alvo central recebe 25% a mais. Recarga de 4 turnos.","kind":"damage","damageT