  ('class', 'ninja', 'Ninja', 'published', $class${"description":"O Ninja combina mobilidade extrema, ferramentas e técnicas encadeadas. Seus Selos registram a ordem das ações e ativam finalizações diferentes, tornando cada turno um pequeno combo. É excelente em entrar, agir e sair, mas exige domínio de sequência e perde potência quando imobilizado ou forçado a repetir ações.","imageUrl":"","difficulty":5,"complexity":"Mestre","specialization":"Híbrido (Assassino / DPS Físico)","primaryAttributes":["FOR","INI"],"affinities":{"FOR":4,"DEF":1,"RES":2,"INI":5,"INT":2,"ARC":2},"mechanic":{"name":"Selos","description":"Recurso exclusivo da classe, desenvolvido pela passiva Sequência de Selos e por suas habilidades."},"passive":{"name":"Sequência de Selos","description":"Usar uma habilidade de Movimento, Ataque ou Técnica registra o Selo correspondente, até 3. Ao obter três Selos, ativa um Final: três diferentes concedem ação de deslocamento livre; dois iguais aumentam em 20% o próximo efeito daquele tipo; três iguais reduzem em 1 turno suas recargas."},"progression":[{"key":"kunai-veloz","name":"Kunai Veloz","level":1,"category":"Ataque","type":"Ativa","effect":"Causa 1x FOR como dano físico em um alvo. Se cumprir a condição central de Selos, causa 0,2x FOR adicional.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1},{"attribute":"FOR","multiplier":0.2}]},{"key":"salto-sobre-telhados","name":"Salto sobre Telhados","level":1,"category":"Mobilidade","type":"Ativa","effect":"Desloca até 2 casas sem provocar a primeira reação comum. Se terminar em posição favorável, gera 1 Selos.","kind":"utility","damageType":"none","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":2,"area":0,"duration":0,"scaling":[]},{"key":"bomba-de-luz","name":"Bomba de Luz","level":10,"category":"Controle","type":"Ativa","effect":"Aplica Lentidão de 20% e impede r