  ('class', 'guerreiro', 'Guerreiro', 'published', $class${"description":"O Guerreiro é o combatente mais versátil da linha de frente. Alterna ofensiva, defesa e proteção sem depender de combinações complexas, tornando-se confiável em qualquer equipe. Possui poucos pontos fracos evidentes, mas seu desempenho máximo é menos explosivo que o de especialistas e depende de escolher a ferramenta certa para cada situação.","imageUrl":"","difficulty":2,"complexity":"Fácil","specialization":"Híbrido (DPS Físico / Tanque)","primaryAttributes":["FOR","DEF"],"affinities":{"FOR":5,"DEF":4,"RES":3,"INI":3,"INT":1,"ARC":1},"mechanic":{"name":"Técnicas","description":"Recurso exclusivo da classe, desenvolvido pela passiva Disciplina Marcial e por suas habilidades."},"passive":{"name":"Disciplina Marcial","description":"A primeira vez em cada turno que o Guerreiro alterna entre uma habilidade Ofensiva e uma Defensiva, recebe Disciplina: +8% de FOR e DEF até o fim do próximo turno. Repetir a mesma categoria mantém consistência, mas não renova o bônus."},"progression":[{"key":"golpe-marcial","name":"Golpe Marcial","level":1,"category":"Ataque","type":"Ativa","effect":"Causa 1x FOR como dano físico em um alvo. Se cumprir a condição central de Técnicas, causa 0,2x FOR adicional.","kind":"damage","damageType":"physical","target":"enemy","resource":"none","cost":0,"cooldown":0,"range":1,"area":0,"duration":0,"scaling":[{"attribute":"FOR","multiplier":1},{"attribute":"FOR","multiplier":0.2}]},{"key":"guarda-alta","name":"Guarda Alta","level":1,"category":"Defesa","type":"Ativa","effect":"Reduz o dano recebido em 23% por 1 turno e concede um escudo de 0,72x DEF. Recarga de 5 turnos.","kind":"shield","damageType":"none","target":"self","resource":"none","cost":0,"cooldown":5,"range":1,"area":0,"duration":1,"scaling":[{"attribute":"DEF","multiplier":0.72}]},{"key":"avanco-com-escudo","name":"Avanço com Escudo","level":10,"category":"Investida","type":"Ativa","effect":"Desloca até 3 casas e at